{
  "probability": 0.58,
  "range_low": 0.50,
  "range_high": 0.66,
  "summary": [
    "Death of Ali Khamenei on February 28, 2026 directly ends his tenure as Supreme Leader.",
    "Iran's constitutional mechanism via the Assembly of Experts provides a path to a successor, potentially with an interim leadership.",
    "State media confirmations and official signaling reinforce a near-term transition timeline, subject to internal dynamics.",
    "Prediction-market signals indicated rising odds of leadership change within 2026, though they remain imperfect indicators.",
    "Overall, the posterior probability is calibrated to about 58%, reflecting strong direct events but acknowledging residual uncertainty in timing and process."
  ],
  "confidence": "medium",
  "narrative": "Starting from a low base-rate anchor, the death confirmation in late February 2026 plus the formal succession mechanism materially shift expectations toward replacement before April 1, 2026. While timing is not guaranteed due to potential intra-elite dynamics, the combination of direct event and institutional pathways yields a calibrated 58% probability with a modest uncertainty range.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Reference class anchor: an elderly male around 86; SSA 2021 period life table death probability ~11.66% per year. This provides a baseline mortality-related cessation risk prior to updates."
    },
    "factor_updates": [
      {
        "factor": "Death of Ali Khamenei on February 28, 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Credible outlets reported confirmed death, which directly ends the incumbent tenure and triggers succession dynamics."
      },
      {
        "factor": "Constitutional mechanism via Assembly of Experts to appoint a successor",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Legal pathway exists for rapid replacement, including potential interim leadership, accelerating cessation timing."
      },
      {
        "factor": "Official confirmation by state media",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "State media affirmation solidifies timeline clarity, though some reporting indicated contested aspects in early coverage."
      },
      {
        "factor": "Progression of interim leadership arrangements",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Reports of transitional governance reduce vacuum risk and support near-term appointment."
      },
      {
        "factor": "Prediction-market signals of leadership change in 2026",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Markets priced higher odds of change within the year, providing supportive, though not definitive, evidence."
      },
      {
        "factor": "Risk of protracted succession contest delaying final appointment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Internal power struggles could slow the pace, introducing downside risk to the exact timing."
      }
    ],
    "synthesis_rationale": "I started with a 0.12 anchor from the elderly-male mortality reference class and applied updates reflecting the February 2026 death (strong upward shift), the constitutional path to replacement (strong), supportive official confirmation (moderate), interim governance signals (moderate), and market signals (weak). The potential for protracted contest dampens the pace, trimming some upside. The resulting posterior of 0.58 represents a calibrated compromise accounting for these correlated updates and residual timing uncertainty."
  }
}

